// OWNER: R6 step 13 FIX round 1, lane 1 (steps\s13\r1_fix_lane1.md). Desktop tests of the two path fixes (src/core/fling_paths.h):
//   PX  the pure rules: race kinds (== the runtime's ForceKnockOk), control hits -> the pre-step path, the fixed-race same-pump kill
//       truth table, the kill delay / instant, Cfg{} = the pre-step path, the shipped ini keys;
//   RG  the regression scenario: the REAL event sequences of the 4 s13g candidate hf runs (tests/s13_fix1_replay.inc, generated by
//       steps\s13\r1_fix_lane1\make_replay.py from work\v2runs) replayed through the rules with the shipped ini: every control hit on
//       the capped essential (HF5) must take the pre-step path (0 executor calls; the candidate made 36), every turret kill (HF2 / HF3,
//       the 12 'immobileRace' 0.3 s freezes) must die in the punch's pump with the instant ragdoll, and every normal knock-now punch must
//       keep the step-13 path exactly. Negative controls: the candidate's keys (look.flingNowControl 1, look.flingImmobile 0)
//       reproduce both failures.
// Build: xmake build s13_fix1_tests ; run from the tree root (reads SuperPeasantNative.ini):
//   build\windows\x64\releasedbg\s13_fix1_tests.exe [--ini <f>]
// Prints S13FIX1|<id>|PASS/FAIL|detail lines; exit 0 = no FAIL. Never shipped.
#include "config.h"
#include "core/fling_look.h"
#include "core/fling_paths.h"

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <format>
#include <string>

namespace
{
	int g_pass = 0, g_fail = 0;
	void Row(const char* a_id, bool a_ok, const std::string& a_detail)
	{
		std::printf("S13FIX1|%s|%s|%s\n", a_id, a_ok ? "PASS" : "FAIL", a_detail.c_str());
		(a_ok ? g_pass : g_fail)++;
	}

	struct ReplayRun
	{
		const char* run;
		const char* hf5;
	};
	struct ReplayEvent
	{
		int           run;
		char          kind;   // 'C' control hit, 'T' fixed-race kill, 'K' a knock-now punch that killed
		double        t;      // s from the run's first event
		std::uint32_t id;
		int           exec;   // the knock-now executor ran on it (candidate)
		double        delay;  // observed s from the punch to the kill ('T'), -1 = none
		double        dynAt;  // FLING|end dynAt ('T'), -1 = not logged
	};
#include "s13_fix1_replay.inc"

	namespace P = sp::flinglook::paths;

	// the runtime's ForceKnockOk (src/runtime.cpp), restated: movable = neither Immobile (bit 9) nor Flies (bit 7), not Liberty Prime
	bool ForceKnockOkRef(std::uint32_t a_flags, std::uint32_t a_id) { return !(a_flags & ((1u << 9) | (1u << 7))) && a_id != 0x00108019u; }

	P::In Shipped(bool a_control, P::Race a_race, bool a_lethal, bool a_killMove = false)
	{
		using sp::cfg::Tunable;
		P::In in;
		in.control = a_control;
		in.controlNow = Tunable("look.flingNowControl", 0.0) != 0;
		in.onceKey = Tunable("look.flingOnce", 0.0) != 0;
		in.immobileKey = Tunable("look.flingImmobile", 0.0) != 0;
		in.immobileOff = false;
		in.brain = true;
		in.race = a_race;
		in.killMove = a_killMove;
		in.lethal = a_lethal;
		return in;
	}
	double DelayOf(bool a_nowKnocked, bool a_deadOnce)
	{
		using sp::cfg::Tunable;
		return P::KillDelay(a_nowKnocked, a_deadOnce, Tunable("punch.nativeDamageDelay", 0.3), Tunable("look.flingOldDelay", 0.3));
	}
}

int main(int argc, char** argv)
{
	std::setvbuf(stdout, nullptr, _IONBF, 0);
	const char* ini = nullptr;
	for (int i = 1; i < argc; ++i)
		if (!std::strcmp(argv[i], "--ini") && i + 1 < argc) ini = argv[++i];
	bool loaded = ini ? sp::cfg::LoadIni(ini) : sp::cfg::LoadIni("SuperPeasantNative.ini");
	if (!loaded && !ini) loaded = sp::cfg::LoadIni("..\\SuperPeasantNative.ini");
	using sp::cfg::Tunable;

	// ---------------------------------------------------------------------------------------------------- PX: the pure rules
	{  // PX-01 race kinds == the runtime's ForceKnockOk for every combination of the low 12 flag bits, with and without Liberty Prime's id
		int bad = 0, n = 0;
		for (std::uint32_t f = 0; f < 4096; ++f)
			for (std::uint32_t id : { 0x00013746u, 0x00108019u }) {
				++n;
				const P::Race r = P::RaceKind(f, id);
				if ((r == P::Race::kMovable) != ForceKnockOkRef(f, id)) ++bad;
				if (id == 0x00108019u && r != P::Race::kLibertyPrime) ++bad;
				if (id != 0x00108019u && (f & (1u << 7)) && r != P::Race::kFlies) ++bad;
				if (id != 0x00108019u && !(f & (1u << 7)) && (f & (1u << 9)) && r != P::Race::kImmobile) ++bad;
			}
		Row("PX-01", bad == 0, std::format("RaceKind vs ForceKnockOk over {} flag/id combinations: {} mismatches (Flies wins over Immobile; Liberty Prime by id)", n, bad));
	}
	{  // PX-02 a control hit never takes the step-13 path (whatever the race / lethality / other keys), unless look.flingNowControl 1
		int bad = 0, n = 0, badNow = 0;
		for (int race = 0; race < 4; ++race)
			for (int bits = 0; bits < 64; ++bits) {
				P::In in;
				in.control = true;
				in.race = static_cast<P::Race>(race);
				in.lethal = bits & 1;
				in.killMove = bits & 2;
				in.onceKey = bits & 4;
				in.immobileKey = bits & 8;
				in.immobileOff = bits & 16;
				in.brain = bits & 32;
				++n;
				in.controlNow = false;
				const P::Out o = P::Choose(in);
				if (o.s13 || o.deadOnce) ++bad;
				in.controlNow = true;
				const P::Out o2 = P::Choose(in);
				if (!o2.s13 || o2.deadOnce) ++badNow;  // the candidate's behaviour: the step path, but never a same-pump kill (no damage)
			}
		Row("PX-02", bad == 0 && badNow == 0, std::format("control hits: {} / {} took the step-13 path with look.flingNowControl 0 (want 0); with 1: {} wrong (want 0)", bad, n, badNow));
	}
	{  // PX-03 a normal punch keeps the step-13 path; a movable / flies / Liberty Prime victim never gets the dead-once path
		int bad = 0, n = 0;
		for (int race = 0; race < 4; ++race)
			for (int bits = 0; bits < 128; ++bits) {
				P::In in;
				in.control = false;
				in.race = static_cast<P::Race>(race);
				in.lethal = bits & 1;
				in.killMove = bits & 2;
				in.onceKey = bits & 4;
				in.immobileKey = bits & 8;
				in.immobileOff = bits & 16;
				in.brain = bits & 32;
				in.controlNow = bits & 64;
				const P::Out o = P::Choose(in);
				++n;
				if (!o.s13) ++bad;
				const bool want = in.race == P::Race::kImmobile && in.lethal && !in.killMove && in.onceKey && in.immobileKey && !in.immobileOff && in.brain;
				if (o.deadOnce != want) ++bad;
			}
		Row("PX-03", bad == 0, std::format("normal punches: {} wrong of {} (s13 path always; dead-once only for a lethal punch on an Immobile race, not a kill-move partner, with "
										  "look.flingOnce + look.flingImmobile on, brain mode, shield not tripped)", bad, n));
	}
	{  // PX-04 the kill delay and the instant flag
		const double nan = std::nan("");
		const bool ok = P::KillDelay(true, false, 0.0, 0.3) == 0.0 && P::KillDelay(false, true, 0.0, 0.3) == 0.0 && P::KillDelay(false, false, 0.0, 0.3) == 0.3 &&
		                P::KillDelay(false, false, 0.5, 0.3) == 0.5 && P::KillDelay(true, false, 0.1, 0.3) == 0.1 && P::KillDelay(false, true, -1.0, 0.3) == 0.0 &&
		                P::KillDelay(false, false, nan, 0.3) == 0.3 && P::KillDelay(true, false, nan, nan) == 0.0 && P::KillInstant(true, true, false) &&
		                !P::KillInstant(true, false, false) && P::KillInstant(false, false, true) && !P::KillInstant(false, true, false);
		Row("PX-04", ok, "KillDelay: knocked-now or dead-once -> punch.nativeDamageDelay, else >= look.flingOldDelay (NaN / negative -> 0); KillInstant: the knock-now rule or dead-once");
	}
	{  // PX-05 the pre-step path: StartFling(.., a_punch = false) reads Cfg{} - every step-13 switch off
		const sp::flinglook::Cfg c{};
		const bool ok = !c.now && !c.once && c.dir == 0 && c.spin == 0 && !(c.gravity > 0) && c.setMotion == 0;
		Row("PX-05", ok, std::format("Cfg{{}} (a control hit's keys) now={} once={} dir={} spin={} gravity={} setMotion={} (want all off = the queued knock + the 0.25 s hold)",
							   c.now, c.once, c.dir, c.spin, c.gravity, c.setMotion));
	}
	{  // PX-06 the shipped ini: the fix keys and the step keys the fix depends on
		const double imm = Tunable("look.flingImmobile", -1.0), ctl = Tunable("look.flingNowControl", 0.0), once = Tunable("look.flingOnce", 0.0),
		             nd = Tunable("punch.nativeDamageDelay", 0.3), sm = Tunable("look.flingSetMotion", 0.0);
		const bool ok = loaded && imm == 1.0 && ctl == 0.0 && once == 1.0 && nd == 0.0 && sm >= 1.0 && Tunable("fo4.forceConvention", 0.0) == 1.0 &&
		                Tunable("brain.range", -1.0) == 1.0 && Tunable("brain.requireCombat", -1.0) == 0.0;
		Row("PX-06", ok, std::format("ini loaded={} look.flingImmobile={} look.flingNowControl={} look.flingOnce={} punch.nativeDamageDelay={} look.flingSetMotion={} (+ the required "
									 "shipped keys)", loaded, imm, ctl, once, nd, sm));
	}

	{  // PX-07 (s13r1 integrator, HF5 in game 10-24: 3 downs / HF3 essential 4 downs with lane 1's fix): a SPARED victim (essential,
	   // spared protected) never takes the step-13 path - control hit or not, any race / keys - unless look.flingNowSpared 1;
	   // a victim that is not spared is unchanged (the PX-02 / PX-03 rules); the shipped ini leaves look.flingNowSpared at 0
		int bad = 0, n = 0, badNow = 0, badOther = 0;
		for (int race = 0; race < 4; ++race)
			for (int bits = 0; bits < 256; ++bits) {
				P::In in;
				in.race = static_cast<P::Race>(race);
				in.control = bits & 1;
				in.lethal = bits & 2;
				in.killMove = bits & 4;
				in.onceKey = bits & 8;
				in.immobileKey = bits & 16;
				in.immobileOff = bits & 32;
				in.brain = bits & 64;
				in.controlNow = bits & 128;
				P::In ns = in;  // the same hit on a victim that is not spared
				in.spared = true;
				++n;
				in.sparedNow = false;
				const P::Out o = P::Choose(in);
				if (o.s13 || o.deadOnce) ++bad;
				in.sparedNow = true;
				const P::Out o2 = P::Choose(in);
				const P::Out o3 = P::Choose(ns);
				if (o2.s13 != o3.s13 || o2.deadOnce != o3.deadOnce) ++badNow;  // look.flingNowSpared 1 = the r1 lanes' rule exactly
				ns.sparedNow = bits & 1;  // the key never changes a victim that is not spared
				const P::Out o4 = P::Choose(ns);
				if (o4.s13 != o3.s13 || o4.deadOnce != o3.deadOnce) ++badOther;
			}
		const double key = Tunable("look.flingNowSpared", 0.0);
		Row("PX-07", bad == 0 && badNow == 0 && badOther == 0 && key == 0.0,
			std::format("spared victims: {} / {} took the step-13 path with look.flingNowSpared 0 (want 0); with 1: {} differ from the r1 lanes' rule (want 0); not spared: {} changed "
						"by the key (want 0); shipped look.flingNowSpared {} (want 0)", bad, n, badNow, badOther, key));
	}

	// ---------------------------------------------------------------------------------------------------- RG: the regression scenario
	const int nRuns = static_cast<int>(sizeof(kReplayRuns) / sizeof(kReplayRuns[0]));
	const int nEv = static_cast<int>(sizeof(kReplayEvents) / sizeof(kReplayEvents[0]));
	{  // RG-01 HF5 / P07: every control hit of the 4 candidate hf runs -> the pre-step path (no executor)
		int ctl = 0, execBefore = 0, execAfter = 0, execCand = 0;
		std::string per;
		for (int r = 0; r < nRuns; ++r) {
			int c = 0, eb = 0, ea = 0;
			for (int i = 0; i < nEv; ++i) {
				const auto& e = kReplayEvents[i];
				if (e.run != r || e.kind != 'C') continue;
				++c;
				eb += e.exec;
				P::In in = Shipped(true, P::Race::kMovable, false);
				if (P::Choose(in).s13 && e.exec) ++ea;  // the executor would still run on this hit
				in.controlNow = true;                    // negative control: the candidate's behaviour
				if (P::Choose(in).s13 && e.exec) ++execCand;
			}
			ctl += c;
			execBefore += eb;
			execAfter += ea;
			per += std::format("{}{}: {} control hits, executor before {} -> after {} (Runner then: {})", per.empty() ? "" : "; ", kReplayRuns[r].run + 9, c, eb, ea, kReplayRuns[r].hf5);
		}
		Row("RG-01", ctl > 0 && execBefore > 0 && execAfter == 0 && execCand == execBefore,
			std::format("HF5 capped essential: {} control hits in {} runs, knock-now executor calls {} -> {} with the shipped keys (negative control look.flingNowControl 1: {} = "
						"the candidate). {}", ctl, nRuns, execBefore, execAfter, execCand, per));
	}
	{  // RG-02 G13-01: every fixed-race kill -> killed in the punch's pump (delay 0, ragdollInstant); look.flingImmobile 0 reproduces the 0.3 s
		int n = 0, freezeBefore = 0, freezeAfter = 0, notInstant = 0, freezeCand = 0;
		double maxObs = 0;
		for (int i = 0; i < nEv; ++i) {
			const auto& e = kReplayEvents[i];
			if (e.kind != 'T') continue;
			++n;
			const double obs = std::max(e.delay, e.dynAt);
			maxObs = std::max(maxObs, obs);
			if (obs >= 0.2) ++freezeBefore;
			P::In in = Shipped(false, P::Race::kImmobile, true);
			const P::Out o = P::Choose(in);
			if (DelayOf(false, o.deadOnce) >= 0.2) ++freezeAfter;
			if (!P::KillInstant(false, false, o.deadOnce)) ++notInstant;
			in.immobileKey = false;  // negative control: the candidate
			if (DelayOf(false, P::Choose(in).deadOnce) >= 0.2) ++freezeCand;
		}
		Row("RG-02", n > 0 && freezeBefore > 0 && freezeAfter == 0 && notInstant == 0 && freezeCand == n,
			std::format("turret kills (HF2 shooting / shot-first, HF3 Combat Zone): {} in {} runs, freezes (kill or limp >= 0.2 s after the punch; observed max {:.2f} s) {} -> {}; "
						"not instant {}; negative control look.flingImmobile 0: {} freezes", n, nRuns, maxObs, freezeBefore, freezeAfter, notInstant, freezeCand));
	}
	{  // RG-03 the normal knock-now punches of the same runs keep the step-13 path exactly (s13, not dead-once, delay 0)
		int n = 0, bad = 0;
		for (int i = 0; i < nEv; ++i) {
			const auto& e = kReplayEvents[i];
			if (e.kind != 'K') continue;
			++n;
			const P::Out o = P::Choose(Shipped(false, P::Race::kMovable, true));
			if (!o.s13 || o.deadOnce || DelayOf(true, false) != 0.0) ++bad;
		}
		Row("RG-03", n > 0 && bad == 0, std::format("normal killing punches (knocked now) in the same runs: {} replayed, {} changed by the fix (want 0)", n, bad));
	}
	{  // RG-04 the fixes never send a protected / special victim down a new path: a vertibird, Liberty Prime, a kill-move turret, a
	   // turret that survives the punch, a control hit on a turret - all keep the old path (no same-pump kill)
		const P::Out a = P::Choose(Shipped(false, P::Race::kFlies, true)), b = P::Choose(Shipped(false, P::Race::kLibertyPrime, true)),
		             c = P::Choose(Shipped(false, P::Race::kImmobile, true, true)), d = P::Choose(Shipped(false, P::Race::kImmobile, false)),
		             e = P::Choose(Shipped(true, P::Race::kImmobile, true));
		const bool ok = !a.deadOnce && !b.deadOnce && !c.deadOnce && !d.deadOnce && !e.deadOnce && !e.s13 && DelayOf(false, a.deadOnce) >= 0.3 - 1e-9;
		Row("RG-04", ok, std::format("vertibird {} / Liberty Prime {} / kill-move turret {} / surviving turret {} / control hit on a turret {} (dead-once: want all 0); their kill delay stays {:.2f} s",
							   a.deadOnce, b.deadOnce, c.deadOnce, d.deadOnce, e.deadOnce, DelayOf(false, false)));
	}
	std::printf("s13_fix1_tests: %d passed, %d failed\n", g_pass, g_fail);
	return g_fail ? 1 : 0;
}
